            "type": "base-mpc-wallet",
            "address": "0x123",
            "linkedUser": "email:user@test.com",
            "createdAt": "2024-01-01"
        }
        mock_request.return_value = mock_response

        result = api_client.create_wallet_for_email("user@test.com", "base")

